  ['friction-fit, turns once/hour']: 'jepit gesek, sekali per jam',
  ['minute wheel · 30']: 'roda menit · 30',
  ['minute pinion · 8 (compound)']: 'pinion roda menit · 8 (majemuk)',
  ['hour wheel · 32']: 'roda jam · 32',
  ['its TUBE carries the hour hand']: 'PIPANYA membawa jarum jam',
  ['30/10 × 32/8']: '30/10 × 32/8',
  ['= 3 × 4 = 12:1']: '= 3 × 4 = 12:1',
  ['the hour hand arrives at 12:1']: 'jarum jam tiba di 12:1',
